text:
I'll create a React error boundary component with fallback UI, retry functionality, and error logging.

## Tool: Write

Parameters:
```json
{
  "file_path": "/repo/ErrorBoundary.tsx",
  "contents": "import React, { Component, ErrorInfo, ReactNode } from "react";

interface Props {
  children: ReactNode;
  fallback?: (error: Error, reset: () => void) => ReactNode;
  onError?: (error: Error, info: ErrorInfo) => void;
}

interface State {
  error: Error | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null };

  static getDerivedStateFromError(error: Error): State {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    console.error("[ErrorBoundary] Uncaught error:", error);
    console.error("[ErrorBoundary] Component stack:", info.componentStack);
    this.props.onError?.(error, info);
  }

  reset = () => this.setState({ error: null });

  render() {
    const { error } = this.state;
    const { children, fallback } = this.props;

    if (error) {
      if (fallback) return fallback(error, this.reset);
      return <DefaultFallback error={error} reset={this.reset} />;
    }

    return children;
  }
}

function DefaultFallback({ error, reset }: { error: Error; reset: () => void }) {
  return (
    <div role="alert" style={styles.container}>
      <h2 style={styles.heading}>Something went wrong</h2>
      <pre style={styles.message}>{error.message}</pre>
      <button onClick={reset} style={styles.button}>
        Try again
      </button>
    </div>
  );
}

const styles: Record<string, React.CSSProperties> = {
  container: {
    padding: "2rem",
    border: "1px solid #f87171",
    borderRadius: "0.5rem",
    background: "#fef2f2",
    color: "#991b1b",
    fontFamily: "sans-serif",
    maxWidth: "480px",
    margin: "2rem auto",
    textAlign: "center",
  },
  heading: {
    margin: "0 0 0.75rem",
    fontSize: "1.25rem",
  },
  message: {
    background: "#fee2e2",
    borderRadius: "0.25rem",
    padding: "0.5rem 0.75rem",
    fontSize: "0.875rem",
    textAlign: "left",
    overflowX: "auto",
    whiteSpace: "pre-wrap",
    wordBreak: "break-word",
  },
  button: {
    marginTop: "1rem",
    padding: "0.5rem 1.25rem",
    background: "#dc2626",
    color: "#fff",
    border: "none",
    borderRadius: "0.375rem",
    fontSize: "0.9rem",
    cursor: "pointer",
  },
};
"
}
```

Done. Here's what was implemented in `ErrorBoundary.tsx`:

**Core behavior:**
- `getDerivedStateFromError` — captures the thrown error into state, triggering the fallback render
- `componentDidCatch` — logs the error and component stack to `console.error`, then calls the optional `onError` prop for external logging (e.g. Sentry)
- `reset` — clears error state so the original children re-render (the retry)

**Props:**
| Prop | Type | Description |
|---|---|---|
| `children` | `ReactNode` | The subtree to protect |
| `fallback` | `(error, reset) => ReactNode` | Optional custom fallback UI |
| `onError` | `(error, info) => void` | Optional external error logger |

**Usage examples:**

```tsx
// Default fallback
<ErrorBoundary>
  <MyComponent />
</ErrorBoundary>

// Custom fallback
<ErrorBoundary
  fallback={(error, retry) => (
    <div>
      <p>Oops: {error.message}</p>
      <button onClick={retry}>Retry</button>
    </div>
  )}
  onError={(error, info) => Sentry.captureException(error, { extra: info })}
>
  <MyComponent />
</ErrorBoundary>
```

Note: Error boundaries must be class components — React does not support this lifecycle pattern in function components.
